 {['inventory','workshop'].includes(view)&&<><section className="cw-live-cart" aria-label="Resumen del carrito"><div><strong>Venta actual</strong><span>{cartUnits} {cartUnits===1?'producto':'productos'} · {labor.length} {labor.length===1?'servicio':'servicios'}</span></div><strong className="cw-live-cart-total">{money(sumMoney([cartTotal,workTotal]))}</strong><Btn tone="primary" onClick={()=>go('sale')}>Ver venta</Btn></section>{saveState()}</>}
 {!['inventory','workshop'].includes(view)&&(draftStatus.status==='loading'||['error','conflict'].includes(draftStatus.status)||operation.current)&&saveState()}
