 {notice&&<div role="status" className="cw-notice"><Glyph name="check"/>{notice}<button className="cw-icon-button" type="button" aria-label="Cerrar aviso" onClick={()=>setNotice('')}><Glyph name="close" size={18}/></button></div>}
 {error&&!modal&&<div role="alert" className="cw-error">{error}</div>}
